<?php require __DIR__.'/../includes/bootstrap.php';admin_required();$id=(int)($_GET['id']??0);$type=$_GET['type']??'';$field=$type==='receipt'?'receipt_path':($type==='facade'?'facade_path':'');if(!$field){http_response_code(404);exit;}$q=db()->prepare("SELECT {$field} AS path FROM orders WHERE id=?");$q->execute([$id]);$path=$q->fetchColumn();if(!$path){http_response_code(404);exit;}$full=realpath(APP_ROOT.'/storage/uploads/'.$path);$base=realpath(APP_ROOT.'/storage/uploads');if(!$full||!str_starts_with($full,$base)){http_response_code(403);exit;}$mime=(new finfo(FILEINFO_MIME_TYPE))->file($full);header('Content-Type: '.$mime);header('Content-Disposition: inline; filename="archivo.'.h(pathinfo($full,PATHINFO_EXTENSION)).'"');readfile($full);